/* One local pet document: resource consumption and rewards commit together. */
(() => {
 const UI=PrototypeUI,D=PrototypeDates,P=PrototypePreferences,KEY='dujia-prototype-pet';
 const actor=()=>P.profile().nickname,peer=()=>UI.read('dujia-prototype-relationship',{})?.partner||'另一半';
 const read=()=>{const value=UI.read(KEY);return value&&typeof value==='object'&&!Array.isArray(value)&&value.id?value:null;};
 const route=pet=>!pet||pet.status==='rejected'?'m07-p04.html':pet.status==='pending'?'m07-p01.html':'m07-p03.html';
 const days=pet=>Math.max(1,Math.round((D.today().time-(D.parse(pet.adoptedDate)?.time||D.today().time))/86400000)+1);
 const todayLogs=pet=>(pet.logs||[]).filter(v=>v.date===D.today().iso);
 const plays=pet=>todayLogs(pet).filter(v=>v.type==='play').length;
 const week=()=>{const date=D.today(),weekday=new Date(date.time).getUTCDay();return D.add(date,-((weekday+6)%7)).iso;};
 const weekCount=pet=>(pet.logs||[]).filter(v=>v.date>=week()&&v.date<=D.today().iso&&['water','play','feed','note'].includes(v.type)).length;
 function commit(pet,operation){if(UI.failNext(operation))throw new Error('操作未完成，请重试；本次数值和库存未改变');return UI.write(KEY,pet);}
 function log(pet,type,text,extra={}){const item={id:crypto.randomUUID(),type,text,actor:actor(),date:D.today().iso,at:Date.now(),...extra};pet.logs.unshift(item);return item;}
 function adopt(kind,name){if(!UI.read('dujia-prototype-relationship',{})?.bound)throw new Error('请先关联另一半，再一起领养');if(read())throw new Error('已有领养记录，请返回宠物空间');return commit({id:crypto.randomUUID(),kind,name,status:'pending',requestedAt:Date.now(),requestedBy:actor(),adoptedDate:null,energy:82,satiety:76,mood:70,affinity:0,food:[12,5,1],gifts:1,coins:0,stars:0,owned:[],outfit:null,room:{},claims:[],logs:[],care:true,settings:{reminder:true,time:'20:30',notes:true,stories:true}},'pet-adopt');}
 function confirmation(){const answer=sessionStorage.getItem('dujia-prototype-peer-pet'),pet=read();if(!answer||pet?.status!=='pending')return pet;if(answer==='accepted'){pet.status='active';pet.adoptedDate=D.today().iso;log(pet,'adopt','共同领养了'+pet.name,{actor:peer()});}else if(answer==='rejected'){pet.status='rejected';}else return pet;if(commit(pet,'pet-confirm'))sessionStorage.removeItem('dujia-prototype-peer-pet');return read();}
 function active(){const pet=read();if(!pet||pet.status!=='active')throw new Error('请先完成共同领养');if(!pet.care||!UI.read('dujia-prototype-relationship',{})?.bound)throw new Error('共同照顾已暂停，宠物和记录仍保留');return pet;}
 const interactions=[{name:'摸摸头',energy:5,affinity:3,mood:2},{name:'丢球球',energy:12,affinity:3,mood:8},{name:'讲故事',energy:8,affinity:6,mood:4},{name:'送小礼物',energy:0,affinity:8,mood:5}];
 function interact(index){const pet=active(),item=interactions[index];if(!item)throw new Error('请选择互动方式');if(plays(pet)>=2)throw new Error('今天已陪伴两次，明天再来；没有断签惩罚');if(pet.energy<item.energy)return {low:true};if(index===3&&pet.gifts<1)throw new Error('礼物已经用完，可通过添水任务获得');const before={energy:pet.energy,affinity:pet.affinity,mood:pet.mood};pet.energy-=item.energy;pet.affinity+=item.affinity;pet.mood=Math.min(100,pet.mood+item.mood);if(index===3)pet.gifts--;const entry=log(pet,'play',item.name,{delta:{energy:pet.energy-before.energy,affinity:pet.affinity-before.affinity,mood:pet.mood-before.mood}});pet.lastInteraction=entry.id;return commit(pet,'pet-play')?{id:entry.id}:null;}
 const foods=[{name:'主粮',satiety:12,mood:0,energy:15},{name:'爱心小饼干',satiety:8,mood:2,energy:8},{name:'草莓布丁',satiety:20,mood:5,energy:20}];
 function feed(index){const pet=active(),item=foods[index];if(!item)throw new Error('请选择食物');if(pet.food[index]<1)return {empty:true};if(pet.satiety>=100&&pet.energy>=100)throw new Error('它已经吃饱且精力充足，留着食物下次再用吧');pet.food[index]--;pet.satiety=Math.min(100,pet.satiety+item.satiety);pet.energy=Math.min(100,pet.energy+item.energy);pet.mood=Math.min(100,pet.mood+item.mood);log(pet,'feed','喂了'+item.name,{food:index});return commit(pet,'pet-feed')?{saved:true}:null;}
 const tasks=[{type:'water',name:'给宠物添水',reward:'主粮 ×1、礼物 ×1'},{type:'play',name:'陪宠物互动',reward:'爱心小饼干 ×1'},{type:'feed',name:'给宠物喂食',reward:'金币 ×20'},{type:'note',name:'记录今天的小心情',reward:'星星 ×5'}];
 const taskState=(pet,type)=>({done:todayLogs(pet).some(v=>v.type===type),claimed:pet.claims.includes(D.today().iso+':'+type)});
 function water(){const pet=active();if(taskState(pet,'water').done)throw new Error('今天已经添过水了');log(pet,'water','添了一碗清水');return commit(pet,'pet-water');}
 function note(text){const pet=active();if(!text.trim()||text.length>500)throw new Error('请填写1至500字的小心情');if(taskState(pet,'note').done)throw new Error('今天的小心情已经记录');log(pet,'note',text.trim());return commit(pet,'pet-note');}
 function claim(type){const pet=active(),weekly=type==='weekly',key=weekly?week()+':weekly':D.today().iso+':'+type,item=tasks.find(v=>v.type===type);if(!weekly&&!item)throw new Error('任务不存在');if(pet.claims.includes(key))throw new Error('奖励已经领取，不会重复到账');if(weekly?weekCount(pet)<3:!taskState(pet,type).done)throw new Error('请先完成任务再领取');if(weekly){if(!pet.owned.includes('小花围巾'))pet.owned.push('小花围巾');}else if(type==='water'){pet.food[0]++;pet.gifts++;}else if(type==='play')pet.food[1]++;else if(type==='feed')pet.coins+=20;else pet.stars+=5;pet.claims.push(key);const entry=log(pet,'reward',weekly?'小花围巾 ×1':item.reward,{claimKey:key});pet.lastReward=entry.id;return commit(pet,'pet-claim')?{id:entry.id}:null;}
 window.PrototypePet={key:KEY,read,route,days,todayLogs,plays,week,weekCount,actor,peer,adopt,confirmation,interact,interactions,feed,foods,tasks,taskState,water,note,claim,commit};
})();
